<?php require_once __DIR__.'/includes/bootstrap.php';require_manager();$pdo=db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$desc=trim($_POST['description']);$amt=(float)$_POST['amount'];if($desc!==''&&$amt>0){$s=$pdo->prepare('INSERT INTO expenses(user_id,description,amount) VALUES(?,?,?)');$s->execute([$_SESSION['user']['id'],$desc,$amt]);$msg='Expense recorded.';}}$rows=$pdo->query('SELECT e.*,u.full_name FROM expenses e JOIN users u ON u.id=e.user_id ORDER BY e.id DESC LIMIT 200')->fetchAll();$pageTitle='Expenses';require 'includes/header.php';?>
<?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><div class="panel"><h2>Record an expense</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div><label>Description</label><input name="description" required placeholder="e.g. Cleaning supplies"></div><div><label>Amount (USD)</label><input name="amount" type="number" min="0.01" step="0.01" required></div><div class="form-action"><button class="btn primary">Save expense</button></div></form></div><div class="panel"><h2>Recent expenses</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Recorded by</th><th>Amount</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d M Y H:i',strtotime($r['expense_date']))?></td><td><?=e($r['description'])?></td><td><?=e($r['full_name'])?></td><td><b><?=money($r['amount'])?></b></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'includes/footer.php';?>
